QS=[
Q('מה המעמד החוקתי של חופש הביטוי?','נגזר מכבוד האדם',['זכות מנויה בחוק היסוד','אינו זכות חוקתית','מוחלט'],'חופש הביטוי נגזר מכבוד האדם, ולכן פגיעה בו נבחנת בפסקת ההגבלה. הוא אינו מנוי במפורש בחוק היסוד ואינו מוחלט, כי ניתן להגבילו כשמתקיימים תנאי הפסקה.'),
Q('מהי פסקת ההגבלה כלפי ביטוי?','בחוק, תכלית ראויה ומידתיות',['אין פסקה','הסכמת הממשלה','רוב של 80'],'פסקת ההגבלה מתירה פגיעה בזכות רק אם היא נעשית בחוק, לתכלית ראויה ובמידה שאינה עולה על הנדרש. הסכמת הממשלה או רוב מיוחד של 80 חברי כנסת אינם תנאי בפסקה.'),
Q('מהו איזון אנכי?','זכות הפרט מול אינטרס ציבורי',['שתי זכויות שוות','שני אינטרסים ציבוריים','חוק מול חוק'],'איזון אנכי הוא איזון בין זכות הפרט לבין אינטרס ציבורי, כמו שלום הציבור או ביטחון. איזון בין שתי זכויות שוות מעמד הוא איזון אופקי, ולכן הוא אינו התשובה לשאלה זו.'),
Q('מהו איזון אופקי?','שתי זכויות שוות מעמד',['זכות מול אינטרס ציבורי','חוק מול תקנה','מדינה מול מדינה'],'איזון אופקי הוא איזון בין שתי זכויות שוות מעמד, כמו חופש הביטוי מול הזכות לשם טוב. איזון בין זכות הפרט לאינטרס ציבורי הוא איזון אנכי, ולכן אינו התשובה.'),
Q('ביטוי מול שם טוב הוא איזון:','אופקי',['אנכי','מנהלי','פלילי'],'שם טוב נגזר מכבוד האדם, והביטוי נגזר גם הוא מכבוד, ולכן ההתנגשות ביניהם היא בין שתי זכויות שוות מעמד ונבחנת באיזון אופקי. איזון אנכי מתאים להתנגשות עם אינטרס ציבורי, כמו שלום הציבור.'),
Q('ביטוי מול שלום הציבור הוא איזון:','אנכי',['אופקי','אזרחי','מסחרי'],'שלום הציבור הוא אינטרס ציבורי ולא זכות של פרט, ולכן התנגשותו עם הביטוי נבחנת באיזון אנכי. איזון אופקי שמור להתנגשות בין זכויות שוות מעמד, כמו ביטוי ושם טוב.'),
Q('מהו חוק איסור לשון הרע?','חוק משנת 1965 המגן על שם טוב',['חוק יסוד','חוק משנת 1992','תקנות הכנסת'],'חוק איסור לשון הרע, התשכ"ה-1965, מגן על שם טוב ומסדיר עוולה אזרחית ועבירה פלילית. חוק משנת 1992 הוא חוק היסוד על כבוד האדם, ותקנות הכנסת אינן מקור לאחריות בלשון הרע.'),
Q('איזו הגנה קיימת בלשון הרע?','אמת בצירוף עניין ציבורי',['שקר','חוסר ידיעה','פרסום סודי'],'ס׳ 14 לחוק איסור לשון הרע מקנה הגנת אמת בפרסום, בתנאי שהיה בו עניין ציבורי, ולכן אמת בצירוף עניין ציבורי היא הגנה. פרסום שקר או בחוסר ידיעה אינו הגנה, ופרסום סודי אינו קשור להגנה.'),
Q('מהי הגנת הפרסום הסביר?','פרסום בבדיקה אחראית של העובדות',['פרסום ללא בדיקה','פרסום בשקר','פרסום בכוונה'],'הגנת הפרסום הסביר דורשת שהמפרסם בדק את העובדות באחריות ובזהירות סבירה לפני הפרסום. פרסום בלי בדיקה, בכוונה לפגוע או בשקר אינו מקים את ההגנה, והוא סותר את דרישת הסבירות.'),
Q('אבנרי נ׳ שפירא עסקה ב:','איזון בין שם טוב לביטוי',['שוויון','קניין','חופש עיסוק'],'בעניין אבנרי נ׳ שפירא נדון האיזון בין חופש הביטוי לשם הטוב בתביעת לשון הרע. חופש עיסוק, שוויון וקניין אינם הנושא המרכזי של הפרשה.'),
Q('איזו הגבלה חמורה יותר?','הגבלה מראש',['אחריות בדיעבד','תביעה אזרחית','תשלום פיצוי'],'הגבלה מראש מונעת את הביטוי מלכתחילה, ולכן פוגעת קשות בחופש הביטוי ובשוק הרעיונות. אחריות בדיעבד, תשלום פיצוי ותביעה אזרחית באים אחרי הפרסום ופוגעים בביטוי פחות, ולכן חמורים פחות.'),
Q('מתי תותר הגבלה מראש?','במקרים קיצוניים לפי ודאות קרובה',['בכל מקרה','לעולם לא','בהחלטת פקיד'],'הגבלה מראש היא חריג קיצוני ותותר רק כשמתקיימת ודאות קרובה לפגיעה חמורה. הטענה שלעולם אינה מותרת קיצונית מדי, והיתר בכל מקרה או בהחלטת פקיד סותר את חזקת החופש.'),
Q('מהו סעיף 144ב לחוק העונשין?','הסתה לגזענות',['לשון הרע','פרטיות','שוחד'],'ס׳ 144ב לחוק העונשין עוסק בפרסום הסתה לגזענות. שוחד, פרטיות ולשון הרע מוסדרים בחוקים ובסעיפים אחרים, ולכן אינם נושא הסעיף.'),
Q('האם ביטוי פוגעני בלבד, ללא הסתה, מוגן?','כן',['לא','רק בכנסת','רק לחברי כנסת'],'ביטוי פוגעני בלבד, שאינו הסתה או עבירה, מוגן, כי הגנה על ביטוי נוח לשומעיו אינה נדרשת. ההגבלה לחברי כנסת או לכנסת בלבד אינה נכונה, והתשובה שאינו מוגן סותרת את הרציונל של הזכות.'),
Q('מהו הקשר בין שם טוב לכבוד?','שם טוב נגזר מכבוד האדם',['שם טוב נגזר מקניין','שם טוב אינו זכות','שם טוב נגזר מעיסוק'],'שם טוב נגזר מכבוד האדם, כי פגיעה במוניטין פוגעת בכבוד ובתדמיתו של האדם. קניין ועיסוק אינם מקור הזכות לשם טוב, והטענה שאינו זכות שגויה, שהרי חוק לשון הרע מגן עליו.'),
Q('בשניצר נקבע:','ודאות קרובה גם בביטחון',['הצנזור חופשי','אין ביקורת','הכנסת מכריעה'],'בעניין שניצר נקבע שמבחן הוודאות הקרובה חל גם על החלטות הצנזורה הצבאית בעניינים ביטחוניים. הטענות שאין ביקורת שיפוטית, שהכנסת מכריעה או שהצנזור חופשי לפסול סותרות את ההלכה.'),
Q('מי נהנה מהגנה חזקה יותר?','ביקורת פוליטית',['לשון הרע פרטית','פרסומת','שקר מכוון'],'ביקורת פוליטית היא ליבת הביטוי, הקרובה ביותר לרציונל הדמוקרטי, ולכן נהנית מהגנה חזקה. פרסומת, שקר מכוון ולשון הרע פרטית רחוקים מהליבה, והגנתם חלשה יותר.'),
Q('מהי ההשפעה של חופש הביטוי על פרשנות לשון הרע?','פרשנות ההגנות ברחבה בעניינים ציבוריים',['ביטול החוק','החמרת החוק','אין השפעה'],'בעקבות חופש הביטוי מפרשים את הגנות לשון הרע ברחבה כשמדובר בעניינים ציבוריים, כדי לא להרתיע מביקורת. הטענה שהחוק הוחמר או בוטל, או שאין השפעה, שגויה.'),
Q('מה נבחן כשהגבלה נעשית בחוק?','פסקת ההגבלה',['חוק הצנזורה','חוק הבחירות','חוק המדינה'],'כשהגבלה נעשית בחוק, בודקים אם היא עומדת בפסקת ההגבלה: חוק, תכלית ראויה ומידתיות. חוק הצנזורה, חוק הבחירות ו"חוק המדינה" אינם מבחן לחוקתיות הפגיעה.'),
Q('מה הסדר הנכון לבחינה?','סוג ביטוי, הגבלה, ערך נוגד, איזון, פסקת הגבלה',['סעד, איזון, ביטוי','הגבלה, סעד, ביטוי','ערך, סעד, חוק'],'שלד הפתרון בנוי בסדר הגיוני: מזהים את סוג הביטוי, את ההגבלה ואת הערך הנוגד, מאזנים, ואז בוחנים את פסקת ההגבלה. סדרים שמתחילים בסעד או בחוק מדלגים על השלבים הראשונים.'),
]
